import Foundation
import SwiftData

/// Built-in calibre catalogue, loaded from Calibers.json (generated by tools/generate_assets.py).
/// A reference only: a calibre gets a `Caliber` record, and with it a place in iCloud, when the
/// user picks it for a barrel, ammunition or entry (`CaliberChoice`) or makes one by hand.
enum CaliberCatalog {
    enum Category: String, CaseIterable {
        case rimfire = "Randfeuer"
        case handgun = "Kurzwaffe"
        case rifle = "Langwaffe"
        case blackPowder = "Schwarzpulver"
        case shotgun = "Flinte"
        case air = "Luftdruck"
        case other = "Andere"
    }

    struct Outline: Decodable {
        let width: Double
        let height: Double
        let `case`: String?
        let head: String?
        let bullet: String?
        /// Paper band drawn over the bullet (paper-patched GP 1890 bullet); nil for jacketed bullets.
        let patch: String?
        /// Bare lead tip of a soft point, drawn over the bullet.
        let tip: String?
        /// "polymer" for a plastic tip; nil for bare lead.
        let tipMaterial: String?
        /// "steel" for the steel head of a hybrid case (.277 SIG Fury); nil for brass.
        let headMaterial: String?
        /// "steel" for a steel-capped nose, "cupronickel" for a silver jacket, "lead" for a bare lead
        /// bullet; nil means a copper-coloured jacket.
        let bulletMaterial: String?
        /// "copper", "steel" (lacquered), "nickel", "paper" or "hybrid" (brass body, steel head) where the case is not brass.
        let caseMaterial: String?
    }

    struct Item: Decodable, Identifiable {
        let id: String
        let name: String
        let category: String
        let aliases: [String]
        /// Printable alternative names, e.g. "9 mm Luger" for 9x19 mm.
        let displayAliases: [String]?
        let kind: String
        /// Shared by cartridges with identical measurements (e.g. .308 Win / 7.62 NATO); nil when alone.
        let dimensionGroup: String?
        /// calibre-data: no longer in regular factory production (surplus, boutique loads, reloading).
        let obsolete: Bool?
        /// calibre-data: unlikely to be found; the pickers keep it behind the search (Raven, 2026-11-12).
        let rare: Bool?
        let outline: Outline
    }

    /// The calibre-data commit the catalogue was generated from (tools/generate_assets.py), shown in Settings.
    struct Source: Decodable {
        let commit: String
        /// The commit's ISO 8601 date. Text, so a date that doesn't parse can't cost the catalogue.
        let date: String

        /// Short commit and its day, e.g. "04653a8 · 8.11.2026".
        var text: String {
            "\(commit.prefix(7)) · \(ISO8601DateFormatter().date(from: date)?.formatted(date: .numeric, time: .omitted) ?? date)"
        }
    }

    struct File: Decodable {
        let calibreData: Source?
        let calibers: [Item]
    }

    private static let file = Bundle.main.url(forResource: "Calibers", withExtension: "json")
        .flatMap { try? Data(contentsOf: $0) }.flatMap(decodeFile)
    static let items: [Item] = file?.calibers ?? []
    static let source: Source? = file?.calibreData

    static func decodeFile(_ data: Data) -> File? { try? JSONDecoder().decode(File.self, from: data) }

    private static let byID = Dictionary(items.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })

    /// Each calibre's name, printed names and search names, normalised once for the calibre search.
    private static let keysByID = Dictionary(
        items.map { ($0.id, ([$0.name] + ($0.displayAliases ?? []) + $0.aliases).map(normalizedAlias)) },
        uniquingKeysWith: { a, _ in a })

    static func searchKeys(id: String) -> [String] { keysByID[id] ?? [] }

    static func item(id: String) -> Item? { byID[id] }

    /// Finds a catalogue entry for free text like "GP90", "9mm", "45 Auto" or ".22 lr".
    static func match(_ text: String) -> Item? {
        let key = normalizedAlias(text)
        guard !key.isEmpty else { return nil }
        return exactMatch(text) ?? items.first { normalizedAlias($0.name).hasPrefix(key) }
    }

    /// The catalogue entry whose name or one of its other names is `text`, spelled any way.
    /// Names win over other names: ".32 S&W" is that calibre, not the .32 S&W Long ("32s&w").
    /// Without `searchNames` only the printed names count, not abbreviations such as "12" or "LG".
    static func exactMatch(_ text: String, searchNames: Bool = true) -> Item? {
        let key = normalizedAlias(text)
        guard !key.isEmpty else { return nil }
        return items.first { normalizedAlias($0.name) == key } ?? items.first {
            ($0.displayAliases ?? []).contains { normalizedAlias($0) == key }
                || (searchNames && $0.aliases.contains { normalizedAlias($0) == key })
        }
    }

    static func normalizedAlias(_ s: String) -> String {
        s.lowercased()
            .replacingOccurrences(of: "×", with: "x")
            .replacingOccurrences(of: ",", with: ".")
            .filter { !$0.isWhitespace }
            .replacingOccurrences(of: "mm", with: "")
            .trimmingCharacters(in: CharacterSet(charactersIn: "."))
    }

    /// Catalogue entries calibre-data renamed, old id to new id (the id is the name). A record on an
    /// old id follows its entry, and takes the new name unless the user renamed it.
    static let renamedIDs = [
        // calibre-data #154: the army's 1892 drawing calls it «Patrone, Modell 1890».
        "7.5x53.5 mm Swiss (GP 1890)": "7.5x53.5 mm Swiss (Patrone Modell 1890)",
    ]

    /// Moves records from a renamed entry's old id to its new one, once the catalogue has the new
    /// one and lost the old one, so it can ship before the catalogue does. Runs at every start.
    /// Returns the number of records moved.
    @MainActor
    @discardableResult
    static func followRenames(_ context: ModelContext, renamed: [String: String] = renamedIDs,
                              inCatalogue: (String) -> Bool = { item(id: $0) != nil }) -> Int {
        guard let all = try? context.fetch(FetchDescriptor<Caliber>()) else { return 0 }
        var moved = 0
        for c in all {
            guard let new = renamed[c.catalogID], inCatalogue(new), !inCatalogue(c.catalogID) else { continue }
            if c.name == c.catalogID { c.name = new }
            c.catalogID = new
            moved += 1
        }
        if moved > 0 { try? context.save() }
        return moved
    }

    /// A catalogue record that holds nothing of the user's (the catalogue's name and category, not
    /// archived, no barrel, ammunition or entry) goes; the catalogue entry stands in for it. A
    /// cancelled picker leaves such records, a backup can bring them back. Runs at every start.
    /// Judged by the relationships, never by a flag, so a record in use anywhere survives.
    /// Returns the number of records removed.
    @MainActor
    @discardableResult
    static func removeUnused(_ context: ModelContext) -> Int {
        guard let all = try? context.fetch(FetchDescriptor<Caliber>()) else { return 0 }
        var removed = 0
        for c in all {
            guard let item = item(id: c.catalogID), !c.isArchived, c.category == item.category, c.name == item.name,
                  (c.barrels ?? []).isEmpty, (c.ammunitions ?? []).isEmpty, (c.entries ?? []).isEmpty else { continue }
            context.delete(c)
            removed += 1
        }
        if removed > 0 { try? context.save() }
        return removed
    }

    /// Two devices can pick the same catalogue calibre before they sync (and every device seeded
    /// the whole catalogue until 2026-11), so the same calibre can arrive twice. Merge duplicates
    /// (same catalogue id) into the oldest record.
    /// Returns the number of records merged away.
    @MainActor
    @discardableResult
    static func deduplicate(_ context: ModelContext) -> Int {
        guard let all = try? context.fetch(FetchDescriptor<Caliber>(sortBy: [SortDescriptor(\.createdAt)])) else { return 0 }
        var keeper: [String: Caliber] = [:]
        var merged = 0
        for c in all where !c.catalogID.isEmpty {
            guard let keep = keeper[c.catalogID] else { keeper[c.catalogID] = c; continue }
            // A freshly seeded duplicate carries no intent of the user, so the oldest record keeps
            // its archived state. Only a duplicate that is actually in use brings the calibre back.
            let inUse = !(c.barrels ?? []).isEmpty || !(c.ammunitions ?? []).isEmpty || !(c.entries ?? []).isEmpty
            for b in c.barrels ?? [] {
                var list = (b.calibers ?? []).filter { $0 != c }
                if !list.contains(keep) { list.append(keep) }
                b.calibers = list
            }
            for a in c.ammunitions ?? [] { a.caliber = keep }
            for e in c.entries ?? [] { e.caliber = keep }
            if inUse, !c.isArchived { keep.isArchived = false }
            context.delete(c)
            merged += 1
        }
        if merged > 0 { try? context.save() }
        return merged
    }
}

/// A calibre as the pickers and lists offer it: the user's record, or a catalogue entry the user
/// has no record of yet. Picking a catalogue entry makes its record (`record(in:)`).
struct CaliberChoice: CaliberLike, Identifiable {
    /// The user's record; nil for a catalogue entry not picked yet.
    let record: Caliber?
    let catalogID: String
    let name: String
    let category: String

    var id: String { record.map { $0.id.uuidString } ?? catalogID }

    init(record: Caliber) {
        self.record = record
        catalogID = record.catalogID
        name = record.name
        category = record.category
    }

    init(item: CaliberCatalog.Item) {
        record = nil
        catalogID = item.id
        name = item.name
        category = item.category
    }

    /// The user's records that are not archived, and the catalogue entries no record stands for.
    /// An archived record hides its entry: the user put that calibre away.
    static func all(_ records: [Caliber]) -> [CaliberChoice] {
        let taken = Set(records.map(\.catalogID))
        return records.filter { !$0.isArchived }.map(CaliberChoice.init(record:))
            + CaliberCatalog.items.filter { !taken.contains($0.id) }.map(CaliberChoice.init(item:))
    }

    /// Firearms with a barrel for this calibre.
    var weapons: [Weapon] { record?.weapons ?? [] }

    /// A catalogue entry calibre-data marks rare, without a record: the pickers and the Kaliber list
    /// show it only when the search has text (Raven, 2026-11-12). The user's records always show.
    var hidden: Bool { record == nil && CaliberCatalog.item(id: catalogID)?.rare == true }

    /// The record, made and inserted now for a catalogue entry: the user picked it.
    @MainActor
    func record(in context: ModelContext) -> Caliber {
        if let record { return record }
        let c = Caliber(name: name, category: category)
        c.catalogID = catalogID
        context.insert(c)
        return c
    }
}
